// Package config loads Hub configuration from the environment.
package config

import "os"

// Config holds the Hub's runtime configuration.
type Config struct {
	// Addr is the listen address for the HTTP server.
	Addr string
	// DatabasePath is the path to the embedded SQLite database.
	DatabasePath string
	// GitHubWebhookSecret verifies the X-Hub-Signature-256 header.
	GitHubWebhookSecret string
	// OTLPEndpoint, when set, is where telemetry is exported (ADR-0008).
	// Empty disables export.
	OTLPEndpoint string
}

// Load reads configuration from the environment, applying defaults.
func Load() Config {
	return Config{
		Addr:                getenv("CAW_ADDR", ":8080"),
		DatabasePath:        getenv("CAW_DB", "caw.db"),
		GitHubWebhookSecret: os.Getenv("CAW_GH_WEBHOOK_SECRET"),
		OTLPEndpoint:        os.Getenv("OTEL_EXPORTER_OTLP_ENDPOINT"),
	}
}

func getenv(key, def string) string {
	if v := os.Getenv(key); v != "" {
		return v
	}
	return def
}

// Package store is the Hub's SQLite-backed persistence layer.
//
// It uses modernc.org/sqlite — a pure-Go (cgo-free) driver — so the Hub
// compiles to a single static binary (ADR-0001).
package store

import (
	"database/sql"
	_ "embed"
	"fmt"
	"time"

	_ "modernc.org/sqlite"
)

//go:embed schema.sql
var schema string

// Store wraps the SQLite database.
type Store struct {
	db *sql.DB
}

// Open opens (creating if needed) the database at path and applies the schema.
func Open(path string) (*Store, error) {
	db, err := sql.Open("sqlite", path)
	if err != nil {
		return nil, fmt.Errorf("open sqlite: %w", err)
	}
	if _, err := db.Exec(schema); err != nil {
		_ = db.Close()
		return nil, fmt.Errorf("apply schema: %w", err)
	}
	return &Store{db: db}, nil
}

// Close closes the underlying database.
func (s *Store) Close() error { return s.db.Close() }

// SeenDelivery records a GitHub delivery id and reports whether it is new.
// It returns true the first time an id is seen, false for duplicates.
func (s *Store) SeenDelivery(id, event string) (bool, error) {
	res, err := s.db.Exec(
		`INSERT OR IGNORE INTO deliveries (id, event, received_at) VALUES (?, ?, ?)`,
		id, event, time.Now().Unix(),
	)
	if err != nil {
		return false, fmt.Errorf("record delivery: %w", err)
	}
	n, err := res.RowsAffected()
	if err != nil {
		return false, fmt.Errorf("delivery rows: %w", err)
	}
	return n == 1, nil
}

// RecordRound upserts the latest-seen timestamp for a PR head SHA (a Round).
func (s *Store) RecordRound(owner, repo string, number int, sha string) error {
	_, err := s.db.Exec(
		`INSERT INTO rounds (owner, repo, number, sha, updated_at) VALUES (?, ?, ?, ?, ?)
		 ON CONFLICT(owner, repo, number, sha) DO UPDATE SET updated_at = excluded.updated_at`,
		owner, repo, number, sha, time.Now().Unix(),
	)
	if err != nil {
		return fmt.Errorf("record round: %w", err)
	}
	return nil
}

// Package github models the subset of GitHub webhook payloads the Hub needs.
package github

// Envelope captures the fields required to bucket a webhook into a Round
// (owner/repo#number @ sha). Different event types carry the PR number and
// head SHA in different places; the optional pointers reflect that.
type Envelope struct {
	Action     string `json:"action"`
	Number     int    `json:"number"`
	Repository struct {
		Name  string `json:"name"`
		Owner struct {
			Login string `json:"login"`
		} `json:"owner"`
	} `json:"repository"`
	PullRequest *struct {
		Number int    `json:"number"`
		State  string `json:"state"`
		Head   struct {
			SHA string `json:"sha"`
		} `json:"head"`
	} `json:"pull_request"`
	CheckSuite *struct {
		HeadSHA      string `json:"head_sha"`
		PullRequests []struct {
			Number int `json:"number"`
		} `json:"pull_requests"`
	} `json:"check_suite"`
}

package hub

import (
	"fmt"

	"github.com/ravencloak-org/caw/internal/github"
)

// RoundKey identifies one settle lifecycle: a PR at a specific head SHA.
type RoundKey struct {
	Owner  string
	Repo   string
	Number int
	SHA    string
}

// String renders the canonical key form owner/repo#number@sha.
func (k RoundKey) String() string {
	return fmt.Sprintf("%s/%s#%d@%s", k.Owner, k.Repo, k.Number, k.SHA)
}

// DeriveRound extracts a RoundKey from a webhook envelope. ok is false when the
// event does not pertain to a specific PR head SHA, in which case the caller
// skips bucketing.
func DeriveRound(env github.Envelope) (key RoundKey, ok bool) {
	owner := env.Repository.Owner.Login
	repo := env.Repository.Name
	if owner == "" || repo == "" {
		return RoundKey{}, false
	}
	switch {
	case env.PullRequest != nil && env.PullRequest.Head.SHA != "":
		return RoundKey{owner, repo, env.PullRequest.Number, env.PullRequest.Head.SHA}, true
	case env.CheckSuite != nil && env.CheckSuite.HeadSHA != "" && len(env.CheckSuite.PullRequests) > 0:
		return RoundKey{owner, repo, env.CheckSuite.PullRequests[0].Number, env.CheckSuite.HeadSHA}, true
	default:
		return RoundKey{}, false
	}
}

// Package hub implements the Caw Hub's HTTP-facing logic: webhook ingest,
// signature verification, delivery dedupe, and Round bucketing.
package hub

import (
	"crypto/hmac"
	"crypto/sha256"
	"encoding/hex"
	"encoding/json"
	"io"
	"log"
	"net/http"
	"strings"

	"github.com/gin-gonic/gin"

	"github.com/ravencloak-org/caw/internal/github"
	"github.com/ravencloak-org/caw/internal/store"
)

// maxBody caps the webhook payload we read (GitHub's documented ceiling is 25 MiB).
const maxBody = 25 << 20

// Hub holds the dependencies for handling webhooks.
type Hub struct {
	store  *store.Store
	secret []byte
}

// New constructs a Hub backed by st, verifying signatures with secret.
func New(st *store.Store, secret []byte) *Hub {
	return &Hub{store: st, secret: secret}
}

// VerifySignature reports whether sigHeader ("sha256=<hex>") is a valid
// HMAC-SHA256 of payload under secret. The comparison is constant-time.
func VerifySignature(secret, payload []byte, sigHeader string) bool {
	const prefix = "sha256="
	if !strings.HasPrefix(sigHeader, prefix) {
		return false
	}
	want, err := hex.DecodeString(sigHeader[len(prefix):])
	if err != nil || len(want) != sha256.Size {
		return false
	}
	mac := hmac.New(sha256.New, secret)
	mac.Write(payload)
	return hmac.Equal(want, mac.Sum(nil))
}

// HandleWebhook is the POST /webhooks/github handler. It verifies the
// signature, dedupes by delivery id, then buckets the event into a Round.
func (h *Hub) HandleWebhook(c *gin.Context) {
	body, err := io.ReadAll(io.LimitReader(c.Request.Body, maxBody))
	if err != nil {
		c.String(http.StatusBadRequest, "read body")
		return
	}

	if len(h.secret) == 0 || !VerifySignature(h.secret, body, c.GetHeader("X-Hub-Signature-256")) {
		c.String(http.StatusUnauthorized, "invalid signature")
		return
	}

	event := c.GetHeader("X-GitHub-Event")
	if delivery := c.GetHeader("X-GitHub-Delivery"); delivery != "" {
		isNew, err := h.store.SeenDelivery(delivery, event)
		if err != nil {
			log.Printf("dedupe delivery %s: %v", delivery, err)
			c.String(http.StatusInternalServerError, "dedupe")
			return
		}
		if !isNew {
			c.String(http.StatusOK, "duplicate")
			return
		}
	}

	var env github.Envelope
	if err := json.Unmarshal(body, &env); err != nil {
		c.String(http.StatusBadRequest, "parse payload")
		return
	}

	if key, ok := DeriveRound(env); ok {
		if err := h.store.RecordRound(key.Owner, key.Repo, key.Number, key.SHA); err != nil {
			log.Printf("record round %s: %v", key, err)
			c.String(http.StatusInternalServerError, "record round")
			return
		}
		log.Printf("bucketed %q into round %s", event, key)
	}

	c.String(http.StatusAccepted, "accepted")
}

