	}

	r := gin.New()
	r.Use(gin.Logger(), gin.Recovery())

	h := hub.New(st, []byte(cfg.GitHubWebhookSecret))
	r.POST("/webhooks/github", h.HandleWebhook)
	r.GET("/healthz", func(c *gin.Context) { c.String(http.StatusOK, "ok") })

	srv := &http.Server{
